import { XAxis as RechartsXAxis, Label } from "recharts";
import { useTheme } from "@theme";

import { XAxisProps } from "../chart.types";
import { useChart } from "../hooks/use-chart";
import { ChartClasses } from "../chart.styles";

const XAxis = (props: XAxisProps) => {
  const theme = useTheme();
  const { handleSort } = useChart();
  const { sortable, dataKey, label: labelProp, ...rest } = props;

  const label = (
    <Label
      className={ChartClasses.xAxisLabel}
      offset={-4}
      position="insideBottom"
      style={{
        cursor: sortable ? "pointer" : undefined,
      }}
      value={String(labelProp ?? "")}
      onClick={
        sortable
          ? (e) => {
              e.preventDefault();
              e.stopPropagation();
              handleSort?.(sortable, dataKey as string);
            }
          : undefined
      }
    />
  );

  return (
    <RechartsXAxis
      stroke={theme.color.border.strong}
      tick={{ fill: theme.color.content.default }}
      tickLine={false}
      {...rest}
      dataKey={dataKey}
      label={label}
    />
  );
};

XAxis.displayName = "XAxis";

export default XAxis;
